const lesson = { meta: { minutes: 20, xp: 80 } };

const { meta: { minutes, xp } } = lesson; // a nested pattern digs into meta in one step
console.log(minutes, xp);                 // 20 80

// Fine print: `meta` itself was a PATH, not a capture — no meta binding exists:
console.log(typeof meta); // "undefined" — only the leaves got names

const scores = [98, 75, 62, 40];

const [first, , third] = scores; // the hole skips index 1 — POSITION is the pattern
console.log(first, third);       // 98 62

const [gold = 'nobody', silver = 'no one'] = ['Ada']; // defaults fire on missing slots
console.log(gold, '|', silver);  // "Ada | no one"

let a = 1;
let b = 2;
[a, b] = [b, a]; // the swap: the right side is built FIRST — [2, 1] — then assigned
console.log(a, b); // 2 1

// The named-arguments pattern: one options object, destructured in the signature
function renderCard({ title = 'Untitled', hours = 6, level = 'beginner' } = {}) {
  return `${title} (${hours}h, ${level})`;
}

console.log(renderCard({ title: 'SQL Basics', hours: 0 })); // "SQL Basics (0h, beginner)" — 0 survives
console.log(renderCard());                                  // "Untitled (6h, beginner)" — = {} caught the no-arg call

function renderCardStrict({ title, hours }) { // WITHOUT the = {} default...
  return `${title} (${hours}h)`;
}
try {
  renderCardStrict(); // destructuring undefined throws
} catch (e) {
  console.log(e.name); // "TypeError"
}

// REST — in a PATTERN (left of = or in a parameter list): gathers many into one
const [head, ...tail] = [1, 2, 3, 4];
const { title, ...restProps } = { title: 'Deep Dive', hours: 8, level: 'advanced' };
console.log(head, '|', tail.join(','));             // "1 | 2,3,4"
console.log(title, '|', JSON.stringify(restProps)); // "Deep Dive | {"hours":8,"level":"advanced"}"

// SPREAD — in a VALUE position (inside a literal or a call): scatters one into many
const merged = [...[1, 2], ...[3, 4]];
const config = { ...{ theme: 'dark' }, retries: 3 };
console.log(merged.join(',')); // "1,2,3,4"
console.log(config.theme, config.retries); // "dark 3"

const a = [1, 2];
const b = [3, 4];

console.log([...a, ...b].join(',')); // "1,2,3,4" — merge without concat
const copy = [...a];                  // a fresh array, same elements
copy.push(99);
console.log(a.join(','), '|', copy.join(',')); // "1,2 | 1,2,99" — the original is untouched

console.log([...'hot'].join('-'));    // "h-o-t" — spread reads ANY iterable, strings included

const defaults = { theme: 'dark', retries: 3, timeout: 5000 };
const overrides = { theme: 'light', timeout: 2000 };

const merged = { ...defaults, ...overrides };  // later keys win
const flipped = { ...overrides, ...defaults };  // order flipped → opposite winner

console.log(merged.theme, merged.retries, merged.timeout); // "light 3 2000"
console.log(flipped.theme, '|', merged.theme);             // "dark | light" — the LAST spread wins

