const COURSE_DEFAULTS = { title: 'Untitled', hours: 6, level: 'beginner' };

function makeLabel({ title = COURSE_DEFAULTS.title, hours = COURSE_DEFAULTS.hours, level = COURSE_DEFAULTS.level } = {}) {
  return `${title} (${hours}h, ${level})`;
}

console.log(makeLabel());                        // Untitled (6h, beginner)
console.log(makeLabel({ title: 'SQL Basics' })); // SQL Basics (6h, beginner)
console.log(makeLabel({ hours: 0 }));            // Untitled (0h, beginner) — 0 survives!

// mergeConfig: overrides win, neither input is mutated
function mergeConfig(base, overrides) {
  return { ...base, ...overrides };
}
const base = { theme: 'dark', retries: 3 };
const config = mergeConfig(base, { retries: 5 });
console.log(config.retries, '|', base.retries); // "5 | 3" — merged won, original kept

// report: a two-line template literal, parameters destructured
function report({ title, hours, level }) {
  return `${title}
${hours}h · ${level} level`;
}
console.log(report({ title: 'SQL Basics', hours: 12, level: 'beginner' }));
// SQL Basics
// 12h · beginner level

