const COURSE_DEFAULTS = { title: 'Untitled', hours: 6, level: 'beginner' };

function makeLabel(options) {
  options = options || {}; // 2013: default the whole object
  const title = options.title || COURSE_DEFAULTS.title;
  const hours = options.hours || COURSE_DEFAULTS.hours; // ← || erases hours: 0
  const level = options.level || COURSE_DEFAULTS.level;
  return title + ' (' + hours + 'h, ' + level + ')';
}

console.log(makeLabel());                        // Untitled (6h, beginner)
console.log(makeLabel({ title: 'SQL Basics' })); // SQL Basics (6h, beginner)
console.log(makeLabel({ hours: 0 }));            // ← the silent bug: predict first, then fix
